import math

def primes(limit):
    """Return a list of all prime numbers less than or equal to `limit`."""
    if limit < 2:
        return []

    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]  # 0 and 1 are not prime

    max_check = int(math.isqrt(limit))
    for p in range(2, max_check + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit+1:p] = [False] * ((limit - start) // p + 1)

    return [i for i, is_prime in enumerate(sieve) if is_prime]
